<script setup lang="ts">
import type { Asset, Incident } from "../types/domain";
defineProps<{ incidents: Incident[]; assetMap: Map<string, Asset>; canOperate: boolean }>();
const emit = defineEmits<{ transition: [incident: Incident, status: Incident["status"]] }>();
function formatTime(value: string) { return new Date(value).toLocaleString("zh-CN", { hour12: false }); }
function statusType(status: string) { return ["CRITICAL", "HIGH"].includes(status) ? "danger" : ["MEDIUM", "ACKNOWLEDGED", "INVESTIGATING"].includes(status) ? "warning" : "info"; }
</script>
<template><section class="view-content"><div class="page-toolbar"><div><span class="section-kicker">INCIDENT RESPONSE</span><p class="toolbar-copy">所有事件都必须关联证据，关闭高风险事件需要处置说明。</p></div></div><section class="panel"><el-table :data="incidents" empty-text="暂无安全事件"><el-table-column label="风险" width="105"><template #default="{ row }"><el-tag :type="statusType(row.severity)" effect="dark">{{ row.severity }}</el-tag></template></el-table-column><el-table-column label="事件" min-width="290"><template #default="{ row }"><strong>{{ row.title }}</strong><small class="table-sub">{{ assetMap.get(row.assetId)?.url }}</small></template></el-table-column><el-table-column prop="occurrenceCount" label="次数" width="80" /><el-table-column prop="status" label="状态" width="145" /><el-table-column label="最近发现" width="180"><template #default="{ row }">{{ formatTime(row.lastSeenAt) }}</template></el-table-column><el-table-column label="处置" width="250"><template #default="{ row }"><el-button v-if="row.status === 'OPEN' && canOperate" link @click="emit('transition', row, 'ACKNOWLEDGED')">认领</el-button><el-button v-if="row.status === 'ACKNOWLEDGED' && canOperate" link @click="emit('transition', row, 'INVESTIGATING')">开始调查</el-button><el-button v-if="row.status === 'INVESTIGATING' && canOperate" type="success" link @click="emit('transition', row, 'RESOLVED')">标记恢复</el-button><el-button v-if="['OPEN', 'INVESTIGATING'].includes(row.status) && canOperate" type="danger" link @click="emit('transition', row, 'FALSE_POSITIVE')">误报</el-button><a class="evidence-link" :href="`/api/v1/reports/${row.id}`">导出证据</a></template></el-table-column></el-table></section></section></template>
